import type { StatsChartRow, StatsDataset } from '../../services/stats/project_stats_service';

const CSV_COLUMNS = [
    'dataset',
    'chart_role',
    'available',
    'grouping',
    'utc_bucket_start',
    'utc_bucket_end',
    'identity',
    'series_identity',
    'series_label',
    'stack_identity',
    'display_label',
    'metric',
    'unit',
    'value',
    'sample_count',
    'completed_count',
    'failed_count',
    'cancelled_count',
];

function csvValue(value: boolean | number | string) {
    const text = String(value);

    return /[",\r\n]/u.test(text) ? `"${text.replaceAll('"', '""')}"` : text;
}

export function serializeStatsCsv(dataset: StatsDataset, rows: StatsChartRow[]) {
    const records = rows.map((row) => [
        dataset,
        row.chartRole,
        row.available,
        row.grouping,
        row.utcBucketStart ?? '',
        row.utcBucketEnd ?? '',
        row.identity,
        row.seriesIdentity ?? '',
        row.seriesLabel ?? '',
        row.stackIdentity ?? '',
        row.displayLabel,
        row.metric,
        row.unit,
        row.value,
        row.sampleCount ?? '',
        row.statusCounts?.completed ?? '',
        row.statusCounts?.failed ?? '',
        row.statusCounts?.cancelled ?? '',
    ]);

    return `${[CSV_COLUMNS, ...records].map((record) => record.map(csvValue).join(',')).join('\r\n')}\r\n`;
}

/** Downloads generated stats CSV without writing repository files. */
export function downloadStatsCsv(dataset: StatsDataset, rows: StatsChartRow[]) {
    const blob = new Blob([serializeStatsCsv(dataset, rows)], { type: 'text/csv;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.download = `md2-stats-${dataset}.csv`;
    anchor.href = url;
    anchor.click();
    URL.revokeObjectURL(url);
}

import { Paper, Stack, Typography } from '@mui/material';
import type { StatsChartRole, StatsChartRow } from '../../services/stats/project_stats_service';
import { StatsBarChart } from './stats_bar_chart';

interface StatsUsageComparisonChartsProps {
    rows: StatsChartRow[];
}

const CHARTS: Array<{ label: string; mode: 'grouped' | 'single' | 'stacked'; role: StatsChartRole }> = [
    { label: 'Project activity', mode: 'stacked', role: 'activity' },
    { label: 'Project token usage', mode: 'grouped', role: 'projectTokens' },
    { label: 'Account usage', mode: 'single', role: 'accountUsage' },
];

/** Three separately scaled charts aligned by shared UTC buckets. */
export function StatsUsageComparisonCharts({ rows }: StatsUsageComparisonChartsProps) {
    return (
        <Stack spacing={2} sx={{ minWidth: '100%', p: 2, width: 'max-content' }}>
            {CHARTS.map(({ label, mode, role }) => (
                <Paper key={role} sx={{ border: 1, borderColor: 'divider', borderRadius: 2, minHeight: 280, overflow: 'hidden' }}>
                    <Typography component="h3" sx={{ px: 2, pt: 1.5 }} variant="subtitle2">{label}</Typography>
                    <StatsBarChart ariaLabel={`${label} chart`} mode={mode} rows={rows.filter(({ chartRole }) => chartRole === role)} />
                </Paper>
            ))}
        </Stack>
    );
}

